INSERT INTO elections(id,title,description,opens_at,closes_at,status,session,form_fee_minor) VALUES('demo-election-2026','NACOS MOUAU 2026 Executive Election (Demo)','A sample election to show how contestants, screening and secret voting work. Only members who have paid the current session dues can vote, and each member votes once.','2026-11-01T00:00:00.000Z','2026-12-31T23:59:00.000Z','voting','2025/2026',100000);
INSERT INTO election_positions(id,election_id,title,display_order) VALUES('demo-pos-president','demo-election-2026','President',1);
INSERT INTO election_positions(id,election_id,title,display_order) VALUES('demo-pos-vice-president','demo-election-2026','Vice President',2);
INSERT INTO election_positions(id,election_id,title,display_order) VALUES('demo-pos-general-secretary','demo-election-2026','General Secretary',3);
INSERT INTO election_positions(id,election_id,title,display_order) VALUES('demo-pos-financial-secretary','demo-election-2026','Financial Secretary',4);
INSERT INTO election_candidates(id,election_id,position_id,user_id,display_name,manifesto,status,screening_note) VALUES('demo-cand-president-1','demo-election-2026','demo-pos-president',NULL,'Adaeze Okonkwo','I will run a NACOS that works for every level: free tutorials every semester, a mentorship programme linking 400 level students to 100 level, and monthly open forums with the executives.','eligible','Demo candidate');
INSERT INTO election_candidates(id,election_id,position_id,user_id,display_name,manifesto,status,screening_note) VALUES('demo-cand-president-2','demo-election-2026','demo-pos-president',NULL,'Chukwudi Eze','My focus is practical tech skills. I will partner with industry for internships, host a hackathon each session, and build a student-run software lab.','eligible','Demo candidate');
INSERT INTO election_candidates(id,election_id,position_id,user_id,display_name,manifesto,status,screening_note) VALUES('demo-cand-president-3','demo-election-2026','demo-pos-president',NULL,'Ifeoma Nwosu','Transparency first: published dues reports, open books and a student welfare fund that members can see and trust.','eligible','Demo candidate');
INSERT INTO election_candidates(id,election_id,position_id,user_id,display_name,manifesto,status,screening_note) VALUES('demo-cand-vice-president-1','demo-election-2026','demo-pos-vice-president',NULL,'Emeka Obi','I will support the President with clear coordination between committees and make sure every decision reaches members quickly.','eligible','Demo candidate');
INSERT INTO election_candidates(id,election_id,position_id,user_id,display_name,manifesto,status,screening_note) VALUES('demo-cand-vice-president-2','demo-election-2026','demo-pos-vice-president',NULL,'Blessing Udoh','Welfare and inclusion: a support desk for new students and a lecture-notes library for every course.','eligible','Demo candidate');
INSERT INTO election_candidates(id,election_id,position_id,user_id,display_name,manifesto,status,screening_note) VALUES('demo-cand-general-secretary-1','demo-election-2026','demo-pos-general-secretary',NULL,'Tochukwu Ibe','Accurate records, timely minutes and a notice board that members actually read.','eligible','Demo candidate');
INSERT INTO election_candidates(id,election_id,position_id,user_id,display_name,manifesto,status,screening_note) VALUES('demo-cand-general-secretary-2','demo-election-2026','demo-pos-general-secretary',NULL,'Grace Ugwu','Digitising our paperwork so every meeting, decision and attendance is searchable.','eligible','Demo candidate');
INSERT INTO election_candidates(id,election_id,position_id,user_id,display_name,manifesto,status,screening_note) VALUES('demo-cand-general-secretary-3','demo-election-2026','demo-pos-general-secretary',NULL,'Samuel Nnadi','Faster communication through a simple WhatsApp and portal notice system.','pending_screening','Awaiting screening');
INSERT INTO election_candidates(id,election_id,position_id,user_id,display_name,manifesto,status,screening_note) VALUES('demo-cand-financial-secretary-1','demo-election-2026','demo-pos-financial-secretary',NULL,'Ngozi Anyanwu','Every naira accounted for, with a termly financial statement presented at the general meeting.','eligible','Demo candidate');
INSERT INTO election_candidates(id,election_id,position_id,user_id,display_name,manifesto,status,screening_note) VALUES('demo-cand-financial-secretary-2','demo-election-2026','demo-pos-financial-secretary',NULL,'Daniel Okafor','Smart dues collection with reminders and receipts so no member is left behind.','eligible','Demo candidate');
INSERT INTO election_candidates(id,election_id,position_id,user_id,display_name,manifesto,status,screening_note) VALUES('demo-cand-financial-secretary-3','demo-election-2026','demo-pos-financial-secretary',NULL,'Peace Amadi','Fundraising partnerships to reduce what members pay while growing our programmes.','pending_payment','Form fee not yet paid');
